    std::unordered_map<char, int> lastPos;
    for (int i = 0; i < s.size(); i++) {
        lastPos[s[i]] = i;
    }

    std::vector<int> partitions;
    int start = 0, end = 0;
    for (int i = 0; i < s.size(); i++) {
        end = std::max(end, lastPos[s[i]]);
        if (i == end) {
            partitions.push_back(end - start + 1);
            start = i + 1;
        }
    }
    return partitions;
}

