def findSubstring(s, t):
    if not s or not t:
        return ""

    t_count = Counter(t)
    s_length = len(s)
    t_length = len(t)
    result = ""
    min_length = float('inf')

    for i in range(s_length - t_length + 1):
        temp_count = Counter()
        for j in range(t_length):
            current_char = s[i + j]
            if current_char not in t_count:
                break
            temp_count[current_char] += 1
            if temp_count[current_char] > t_count[current_char]:
                break
            if j + 1 == t_length:
                if i + t_length < min_length:
                    min_length = i + t_length
                    result = s[i:i + t_length]

    return result
