class Node:
    def __init__(self, val, prev, next, child):
        self.val = val
        self.prev = prev
        self.next = next
        self.child = child

def flatten(head: Node) -> Node:
    if not head:
        return None

    cur, prev, next_node = head, None, None

    while cur:
        next_node = cur.next

        if cur.child:
            cur.next = flatten(cur.child)
            cur.child.prev = cur
            cur.child = None

            if next_node:
                prev = cur
                while cur.next:
                    cur = cur.next
                    prev = prev.next

                cur.next = next_node
                next_node.prev = prev

        cur = next_node

    return head

def flatten_to_list(root: Node) -> list:
    result = []
    stack = [root]

    while stack:
        node = stack.pop()
        result.append(node.val)

        if node.child:
            stack.append(node.child)

        if node.next:
            stack.append(node.next)

    return result
```


